public boolean isPlayerOnTeam(Player player, TeamData teamData) {
    return FTBTeamsAPI.api().getManager().getTeamForPlayerID(player.m_20148_()).map(team -> team.getTeamId().equals(teamData.getTeamId())).orElse(false);
}

